package com.fasterxml.jackson.dataformat.xml.deser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.ObjectCodec;
import com.fasterxml.jackson.dataformat.xml.PackageVersion;
import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.Set;
import javax.xml.stream.XMLStreamReader;
import javax.xml.stream.XMLStreamWriter;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for FromXmlParser.nextTextValue().
 * Using reflection to inject private fields for high-coverage testing.
 */
public class FromXmlParser_nextTextValue_TriageGen1Test {

    private FromXmlParser parser;

    @Mock private IOContext ioContext;
    @Mock private ObjectCodec codec;
    @Mock private XMLStreamReader xmlReader;
    @Mock private XmlXmlTokens xmlTokens; // Mocking the internal _xmlTokens wrapper
    @Mock private ParsingContext parsingContext;
    @Mock private ParsingContext parentContext;

    // Constants to match internal logic
    private static final int XML_START_ELEMENT = 1;
    private static final int XML_END_ELEMENT = 2;
    private static final int XML_ATTRIBUTE_NAME = 3;
    private static final int XML_ATTRIBUTE_VALUE = 4;
    private static final int XML_TEXT = 5;
    private static final int XML_END = 6;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);

        // Initialize parser
        parser = new FromXmlParser(ioContext, 0, 0, codec, xmlReader);

        // Inject mocks into private fields using reflection
        setField("_xmlTokens", xmlTokens);
        setField("_parsingContext", parsingContext);
        setField("_mayBeLeaf", false);
        setField("_nextToken", null);
        setField("_currToken", null);
        setField("_currText", null);
        setField("_cfgNameForTextElement", "textElement");

        // Setup default behavior for context
        when(parsingContext.createChildObjectContext(anyInt(), anyInt())).thenReturn(parsingContext);
        when(parsingContext.getParent()).thenReturn(parentContext);
        when(parentContext.getNamesToWrap()).thenReturn(null);
    }

    private void setField(String name, Object value) throws Exception {
        Field field = FromXmlParser.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(parser, value);
    }

    @Test
    public void testNextTextValue_AlreadyHasNextToken_IsString() throws Exception {
        setField("_nextToken", JsonToken.VALUE_STRING);
        setField("_currText", "hello");

        String result = parser.nextTextValue();

        assertEquals("hello", result);
        assertNull(parser.nextTextValue() == null ? null : "logic error"); // check _nextToken is null now
    }

    @Test
    public void testNextTextValue_AlreadyHasNextToken_NotString() throws Exception {
        setField("_nextToken", JsonToken.START_OBJECT);

        // This triggers _updateState(t)
        String result = parser.nextTextValue();

        assertNull(result);
    }

    @Test
    public void testNextTextValue_XmlStartElement_MayBeLeafTrue() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_START_ELEMENT);
        setField("_mayBeLeaf", true);

        String result = parser.nextTextValue();

        assertNull(result);
        assertEquals(JsonToken.FIELD_NAME, getField("_nextToken"));
        assertEquals(JsonToken.START_OBJECT, getField("_currToken"));
        verify(parsingContext).createChildObjectContext(-1, -1);
    }

    @Test
    public void testNextTextValue_XmlStartElement_InArray() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_START_ELEMENT);
        setField("_mayBeLeaf", false);
        when(parsingContext.inArray()).thenReturn(true);

        String result = parser.nextTextValue();

        assertNull(result);
        verify(xmlTokens, atLeastOnce()).next();
        assertTrue((Boolean) getField("_mayBeLeaf"));
    }

    @Test
    public void testNextTextValue_XmlStartElement_Normal() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_START_ELEMENT);
        setField("_mayBeLeaf", false);
        when(parsingContext.inArray()).thenReturn(false);
        when(xmlTokens.getLocalName()).thenReturn("testName");

        String result = parser.nextTextValue();

        assertNull(result);
        verify(parsingContext).setCurrentName("testName");
        assertEquals(JsonToken.FIELD_NAME, getField("_currToken"));
    }

    @Test
    public void testNextTextValue_XmlStartElement_WithNamesToWrap() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_START_ELEMENT);
        setField("_mayBeLeaf", false);
        when(parsingContext.inArray()).thenReturn(false);
        when(xmlTokens.getLocalName()).thenReturn("wrapped");

        java.util.Set<String> namesToWrap = java.util.Collections.singleton("wrapped");
        setField("_namesToWrap", namesToWrap);

        parser.nextTextValue();

        verify(xmlTokens).repeatStartElement();
    }

    @Test
    public void testNextTextValue_XmlEndElement_MayBeLeafTrue() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_END_ELEMENT);
        setField("_mayBeLeaf", true);

        String result = parser.nextTextValue();

        assertEquals("", result);
        assertFalse((Boolean) getField("_mayBeLeaf"));
        assertEquals(JsonToken.VALUE_STRING, getField("_currToken"));
    }

    @Test
    public void testNextTextValue_XmlEndElement_NotInArray() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_END_ELEMENT);
        setField("_mayBeLeaf", false);
        when(parsingContext.inArray()).thenReturn(false);

        String result = parser.nextTextValue();

        assertNull(result);
        assertEquals(JsonToken.END_OBJECT, getField("_currToken"));
        verify(parsingContext).getParent();
        verify(parentContext).getNamesToWrap();
    }

    @Test
    public void testNextTextValue_XmlEndElement_InArray() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_END_ELEMENT);
        setField("_mayBeLeaf", false);
        when(parsingContext.inArray()).thenReturn(true);

        String result = parser.nextTextValue();

        assertNull(result);
        assertEquals(JsonToken.END_ARRAY, getField("_currToken"));
    }

    @Test
    public void testNextTextValue_XmlAttributeName_MayBeLeafTrue() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_ATTRIBUTE_NAME);
        setField("_mayBeLeaf", true);
        when(xmlTokens.getText()).thenReturn("attrVal");

        String result = parser.nextTextValue();

        assertNull(result);
        assertFalse((Boolean) getField("_mayBeLeaf"));
        assertEquals(JsonToken.FIELD_NAME, getField("_nextToken"));
        assertEquals("attrVal", getField("_currText"));
        assertEquals(JsonToken.START_OBJECT, getField("_currToken"));
        verify(parsingContext).createChildObjectContext(-1, -1);
    }

    @Test
    public void testNextTextValue_XmlAttributeName_Normal() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_ATTRIBUTE_NAME);
        setField("_mayBeLeaf", false);
        when(xmlTokens.getLocalName()).thenReturn("attrName");

        String result = parser.nextTextValue();

        assertNull(result);
        verify(parsingContext).setCurrentName("attrName");
        assertEquals(JsonToken.FIELD_NAME, getField("_currToken"));
    }

    @Test
    public void testNextTextValue_XmlAttributeValue() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_ATTRIBUTE_VALUE);
        when(xmlTokens.getText()).thenReturn("val");

        String result = parser.nextTextValue();

        assertNull(result);
        assertEquals("val", getField("_currText"));
        assertEquals(JsonToken.VALUE_STRING, getField("_currToken"));
    }

    @Test
    public void testNextTextValue_XmlText_MayBeLeafTrue() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_TEXT);
        when(xmlTokens.getText()).thenReturn("textContent");
        setField("_mayBeLeaf", true);

        String result = parser.nextTextValue();

        assertEquals("textContent", result);
        assertFalse((Boolean) getField("_mayBeLeaf"));
        verify(xmlTokens).skipEndElement();
        assertEquals(JsonToken.VALUE_STRING, getField("_currToken"));
    }

    @Test
    public void testNextTextValue_XmlText_Normal() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_TEXT);
        when(xmlTokens.getText()).thenReturn("textContent");
        setField("_mayBeLeaf", false);

        String result = parser.nextTextValue();

        assertNull(result);
        verify(parsingContext).setCurrentName("textElement");
        assertEquals(JsonToken.VALUE_STRING, getField("_nextToken"));
        assertEquals(JsonToken.FIELD_NAME, getField("_currToken"));
    }

    @Test
    public void testNextTextValue_XmlEnd() throws Exception {
        when(xmlTokens.next()).thenReturn(XML_END);

        String result = parser.nextTextValue();

        assertNull(result);
        assertNull(getField("_currToken"));
    }

    private Object getField(String name) throws Exception {
        Field field = FromXmlParser.class.getDeclaredField(name);
        field.setAccessible(true);
        return field.get(parser);
    }
}
